#include <iostream>
#include <list>

int main() {
    std::list<int> values = {1, 2, 4, 4, 6};
    std::list<int> otherValues = {3, 5, 7};

    // Merge otherValues into values (both already sorted)
    values.merge(otherValues);
    std::cout << "Merged values:";
    for (int n : values) {
        std::cout << " " << n;
    }
    std::cout << "\notherValues is empty: " << (otherValues.empty() ? "true" : "false") << "\n";

    // Remove consecutive duplicates
    values.unique();
    std::cout << "After unique:";
    for (int n : values) {
        std::cout << " " << n;
    }
    std::cout << "\n";

    // Remove all nodes with value 4
    values.remove_if([](int value){return value == 4;});
    std::cout << "After remove(4):";
    for (int n : values) {
        std::cout << " " << n;
    }
    std::cout << "\n";

    return 0;
}

#include <iostream>
#include <deque>

int main() {
    std::deque<double> values;

    // Insert elements at front and back
    values.push_front(2.2);
    values.push_front(3.5);
    values.push_back(1.1);

    std::cout << "values contains:";
    for (size_t i = 0; i < values.size(); ++i) {
        std::cout << " " << values[i];
    }
    std::cout << "\n";

    // Remove first element
    values.pop_front();
    std::cout << "After pop_front:";
    for (double v : values) {
        std::cout << " " << v;
    }
    std::cout << "\n";

    // Modify element at index 1 via subscript lvalue
    values[1] = 5.4;
    std::cout << "After values[1] = 5.4:";
    for (double v : values) {
        std::cout << " " << v;
    }
    std::cout << "\n";

    return 0;
}

#include <iostream>
#include <set>

int main() {
    // multiset sorted ascending with std::less<int> (default)
    std::multiset<int> intMultiset;

    std::cout << "Initial count of 15: " << intMultiset.count(15) << "\n";
    intMultiset.insert(15);
    intMultiset.insert(15);
    std::cout << "Count of 15 after inserts: " << intMultiset.count(15) << "\n";

    // Search using find()
    auto it15 = intMultiset.find(15);
    if (it15 != intMultiset.end()) {
        std::cout << "Found value 15\n";
    }

    auto it20 = intMultiset.find(20);
    if (it20 == intMultiset.end()) {
        std::cout << "Did not find value 20\n";
    }

    // Insert values from an array/list; multiset automatically maintains sorted order
    int arr[] = {7, 22, 9, 1, 18, 30, 100, 22, 85, 13};
    for (int x : arr) {
        intMultiset.insert(x);
    }

    std::cout << "Sorted multiset contents:";
    for (int x : intMultiset) {
        std::cout << " " << x;
    }
    std::cout << "\n";

    return 0;
}
